create or replace function public.advance_delivery_assignment(p_assignment_id uuid, p_next_status text, p_note text default null) returns public.delivery_assignments language plpgsql security definer set search_path=public as $$ declare v_assignment public.delivery_assignments; v_staff public.staff; v_now timestamptz := now(); v_ship public.shipments; begin select * into v_staff from public.staff where id=(select id from public.staff where id in (select assigned_staff_id from public.delivery_assignments where id=p_assignment_id) limit 1); select * into v_assignment from public.delivery_assignments where id=p_assignment_id for update; if not found then raise exception 'Assignment not found'; end if; select * into v_staff from public.staff where id=v_assignment.assigned_staff_id and is_active=true; if not found then raise exception 'Assigned staff is inactive or missing'; end if; if p_next_status not in ('assigned','accepted','picked_up','out_for_delivery','delivered','failed','cancelled') then raise exception 'Invalid delivery status'; end if; if p_next_status='accepted' and v_assignment.status not in ('assigned') then raise exception 'Invalid transition'; end if; if p_next_status='picked_up' and v_assignment.status not in ('accepted') then raise exception 'Invalid transition'; end if; if p_next_status='out_for_delivery' and v_assignment.status not in ('picked_up') then raise exception 'Invalid transition'; end if; if p_next_status='delivered' and v_assignment.status not in ('out_for_delivery') then raise exception 'Invalid transition'; end if; if p_next_status in ('failed','cancelled') and v_assignment.status in ('delivered','cancelled') then raise exception 'Invalid transition'; end if; update public.delivery_assignments set status=p_next_status, pickup_at=case when p_next_status='picked_up' and pickup_at is null then v_now else pickup_at end, delivered_at=case when p_next_status='delivered' then coalesce(delivered_at,v_now) else delivered_at end, note=coalesce(p_note,note), updated_at=v_now where id=p_assignment_id returning * into v_assignment; update public.shipments set operational_status=case p_next_status when 'accepted' then 'assigned' when 'picked_up' then 'picked_up' when 'out_for_delivery' then 'out_for_delivery' when 'delivered' then 'delivered' when 'failed' then 'delayed' when 'cancelled' then 'cancelled' else operational_status end, tracking_updated_at=v_now where id=v_assignment.shipment_id returning * into v_ship; insert into public.shipment_events (shipment_id,event_type,status,note,occurred_at,created_by,created_by_name,metadata) values (v_assignment.shipment_id,'delivery_status',p_next_status,p_note,v_now,v_staff.id,v_staff.full_name,jsonb_build_object('assignment_id',v_assignment.id)); insert into public.staff_activity_log (staff_id,staff_name,action,target_id,details,created_at) values (v_staff.id,v_staff.full_name,'delivery_status_changed',v_assignment.shipment_id,coalesce(p_note,'status='||p_next_status),v_now); if v_ship.customer_user_id is not null then insert into public.customer_notifications(customer_user_id,shipment_id,kind,title,body,action_url) values (v_ship.customer_user_id,v_ship.id,'shipment',case p_next_status when 'picked_up' then 'بارەکەت وەرگیرا' when 'out_for_delivery' then 'بارەکەت لە ڕێگادایە' when 'delivered' then 'بارەکەت گەیشت' else 'نوێکردنەوەی بار' end,coalesce(p_note,'Status updated to '||p_next_status),'/tracking.html?tracking='||v_ship.id); end if; return v_assignment; end; $$; revoke all on function public.advance_delivery_assignment(uuid,text,text) from public, anon, authenticated; grant execute on function public.advance_delivery_assignment(uuid,text,text) to authenticated;;
